  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  IMPORT_BARRIER_SHARES,
  JUNE_FLOW,
  LENS_COMPARE,
  PACKAGE_CONCENTRATION_CURVE,
  PACKAGE_SHARES,
  SOURCE_NOTE,
  SOURCES,
  STOCK_CONCENTRATION_CURVE,
  STOCK_SHARES,
  STRATEGIC_INTENSITY,
  VINTAGE_CHECKS,
  fmtBn,
  fmtPct,
} from "@/data/fiscal-industrial-policy-concentration-2026-data";

// viz-types: Lorenz area+line, ranked share bars, package pie, strategic dumbbell, lens scatter, flow donut | layout: default

type ViewId = "ladder" | "packages" | "strategic" | "flow";
type LadderMetric = "sharePct" | "cumulative";
type PackageMetric = "usdBn" | "sharePct";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";
const AMBER = "#f59e0b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
