            onClick={() => onSelect(d.country)}
            className={`grid w-full grid-cols-[6.5rem_1fr_7rem] items-center gap-2 rounded-lg px-2 py-1 text-left transition ${
              active ? "bg-slate-50" : "opacity-35"
