              <title>{`${d.country}: mine ${fmtPct(d.minePct)} ?? refine ${fmtPct(d.refinePct)}`}</title>
              <line
                x1={xM}
                y1={11}
                x2={xR}
                y2={11}
                stroke="#94a3b8"
                strokeWidth={2}
              />

    return <IndustrialRoboticsConcentration2026q3Dashboard />;
