                  >
                    {US_STATE_AWARDS.map((s) => (
                      <Cell
                        key={s.state}
                        fill={s.fill}
                        opacity={
                          !highlightState || highlightState === s.state
                            ? 1
                            : 0.35
                        }
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v), 1), "Share"]}
