                  <Bar dataKey="N. America" stackId="a" fill="#0ea5e9" />
                  <Bar dataKey="Europe" stackId="a" fill="#8b5cf6" />
                  <Bar
                    dataKey="RoW"
                    stackId="a"
                    fill="#64748b"
                    radius={[4, 4, 0, 0]}
