                  <XAxis
                    dataKey="short"
                    tick={{ fill: "#64748b", fontSize: 11 }}
                  />
                  <YAxis
                    tickFormatter={(v) => `${v}%`}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      fmtPct(Number(v), 1),
